-- Atomic coaching-text-only update. Explicit before/after guards prevent lost edits.
-- No video, name, code, category, active status, default dosage or programme changes.
DO $coaching$
DECLARE
  changes jsonb := $changes$[{"code":"ACC01","name":"Wall March","video_id":"bBfLvmrHDkc","video_url":"https://www.youtube.com/shorts/bBfLvmrHDkc","before":{"purpose":"Practise acceleration posture and controlled single-leg support.","description":"Face a stable wall with hands at shoulder height. Lean from your ankles in a straight line; lift one knee, place the foot back under your hip and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Long body. Hips forward. Foot under hip. Avoid: Folding at the waist, arching the lower back or reaching the foot ahead.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Acceleration-day bridge","description":"Lean into the wall and raise one knee at a time.","coaching_cues":"Cue: Straight body. Knee up. Avoid: Do not bend at your hips.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACC02","name":"Wall Switch","video_id":"aIRTnxFAZNE","video_url":"https://www.youtube.com/shorts/aIRTnxFAZNE","before":{"purpose":"Practise coordinated leg exchanges while holding an acceleration position.","description":"Set a straight-body lean against a stable wall. Exchange the raised and supporting legs as demonstrated, landing the supporting foot under the hip; reset if posture changes. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Push the wall. Switch under hips. Keep your shape. Avoid: Bouncing the hips, collapsing through the shoulders or trading control for speed.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Acceleration-day bridge","description":"Lean into the wall and quickly switch your legs.","coaching_cues":"Cue: Switch fast. Stay tall. Avoid: Do not let your hips drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACC03","name":"Falling Start","video_id":"IdFSYpV9z20","video_url":"https://www.youtube.com/shorts/IdFSYpV9z20","before":{"purpose":"Practise projecting the body into the first acceleration steps.","description":"On a clear, non-slip lane, stand tall with feet under hips. Lean forward from the ankles until a step is needed, then push into the assigned run and slow down beyond the finish. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Lean as one. Push away. Rise gradually. Avoid: Bending at the waist, falling beyond control or stopping abruptly at the finish.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Acceleration-day bridge","description":"Lean forward as one straight body and run when you begin to fall.","coaching_cues":"Cue: Lean, then push away. Avoid: Do not bend at your waist.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACC04","name":"Two-Point Start","video_id":"sD1iGWZ_4Qs","video_url":"https://www.youtube.com/shorts/sD1iGWZ_4Qs","before":{"purpose":"Practise a balanced standing start and purposeful first steps.","description":"Use a staggered stance on a clear lane, with the front foot loaded and arms ready. Push into the first steps and let the body rise as speed builds. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Push back. Drive arms. Rise with speed. Avoid: Reaching for a long first step, jumping upward or forcing the head down.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Weeks 1–4 acceleration","description":"Start with one foot forward and push hard into your first steps.","coaching_cues":"Cue: Push the ground back. Avoid: Do not stand up too early.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACC05","name":"10–30m Acceleration","video_id":"","video_url":"","before":{"purpose":"Build speed through progressive acceleration over the assigned distance.","description":"Use the start Coach Du assigns and check the lane and run-out are clear. Accelerate over the prescribed 10–30 m at the assigned effort, then ease down gradually. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Push with intent. Build each step. Run through the finish. Avoid: Overstriding, forcing a low posture or adding distance or effort beyond the programme.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Covers the main acceleration family","description":"Accelerate hard over the set distance and build speed with each step.","coaching_cues":"Cue: Push hard. Rise smoothly. Avoid: Do not stand up too early.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT01","name":"Glute Bridge","video_id":"nD1CM76NlVs","video_url":"https://www.youtube.com/shorts/nD1CM76NlVs","before":{"purpose":"Develop controlled hip extension using the glute muscles.","description":"Lie on your back on a mat with knees bent and feet flat. Press through the feet to lift the hips in line with the trunk, then lower smoothly. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Ribs settled. Squeeze glutes. Lower slowly. Avoid: Pushing so high that the lower back arches, or letting the knees drift inward.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Warm-up + home support","description":"Lie on your back and lift your hips up.","coaching_cues":"Cue: Squeeze your hips at the top. Avoid: Do not bend your lower back.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT02","name":"Single-Leg Glute Bridge","video_id":"zZD--pmOBLM","video_url":"https://www.youtube.com/shorts/zZD--pmOBLM","before":{"purpose":"Develop hip extension and pelvic control on one supporting leg.","description":"Lie on your back with one foot planted and the other leg held as demonstrated. Lift and lower the hips while keeping both sides of the pelvis level; use the assigned range. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Level hips. Push through the planted foot. Control down. Avoid: Twisting the pelvis, arching the lower back or continuing through cramp or pain.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Warm-up + Week 1 strength","description":"Lift your hips with one foot on the floor.","coaching_cues":"Cue: Keep your hips level. Avoid: Do not let one hip drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT03","name":"Side-Lying Hip Abduction","video_id":"c3eH-sc8uBM","video_url":"https://www.youtube.com/shorts/c3eH-sc8uBM","before":{"purpose":"Develop controlled strength at the side of the hip.","description":"Lie on your side with the pelvis stacked and the top leg long. Lift that leg a small distance from the hip, then lower slowly without rolling the trunk. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Stack hips. Reach long. Lower slowly. Avoid: Rolling backward, turning the toes upward to gain height or lifting beyond control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Hip strength and control.","description":"Lie on your side and lift the top leg up and down.","coaching_cues":"Cue: Toes forward. Lift from the hip. Avoid: Do not roll backward.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT04","name":"Clamshell","video_id":"SRLwCVGL53E","video_url":"https://www.youtube.com/shorts/SRLwCVGL53E","before":{"purpose":"Practise hip rotation while keeping the pelvis stable.","description":"Lie on your side with hips and knees bent, feet together. Open the top knee only as far as you can without rolling backward, then close slowly. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Feet together. Hips stacked. Open from the hip. Avoid: Twisting the lower back, rolling the pelvis or forcing a large range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Hip strength and control.","description":"Lie on your side with knees bent and lift the top knee.","coaching_cues":"Cue: Keep your feet together. Avoid: Do not roll your body backward.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT05","name":"Fire Hydrant","video_id":"s73ByyYa1l4","video_url":"https://www.youtube.com/shorts/s73ByyYa1l4","before":{"purpose":"Develop hip control while maintaining a stable trunk.","description":"Start on hands and knees on a mat. With the knee bent, lift one thigh out to the side within a comfortable range and return slowly. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Hands under shoulders. Hips level. Move from the hip. Avoid: Leaning away, arching the back or rotating the whole pelvis.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Hip strength and control.","description":"From hands and knees, lift one bent leg out to the side.","coaching_cues":"Cue: Keep your body still. Avoid: Do not twist your hips.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT06","name":"Lateral Band Walk","video_id":"vAUZlEFjM9U","video_url":"https://www.youtube.com/shorts/vAUZlEFjM9U","before":{"purpose":"Develop lateral hip control while stepping against a band.","description":"Place a resistance band where shown in the demo and take a small athletic stance. Step sideways, then bring the trailing foot in under control while keeping band tension. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Small steps. Knees follow toes. Control the trailing foot. Avoid: Dragging the feet, snapping them together or using a band too strong to control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Hip strength and lateral control.","description":"Bend slightly and take small steps sideways against the band.","coaching_cues":"Cue: Stay low. Keep band tension. Avoid: Do not let your feet snap together.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT07","name":"Monster Walk","video_id":"K-RCj59qZ5Y","video_url":"https://www.youtube.com/shorts/K-RCj59qZ5Y","before":{"purpose":"Develop hip control during resisted diagonal stepping.","description":"Use the band position and walking direction demonstrated. Take short diagonal steps from a comfortable athletic stance, maintaining controlled band tension. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Steady hips. Small steps. Keep tension. Avoid: Swaying the trunk, letting knees collapse inward or overstretching the band.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Hip strength and movement control.","description":"Take small diagonal steps while keeping tension on the band.","coaching_cues":"Cue: Stay strong and controlled. Avoid: Do not let your knees fall in.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT08","name":"Single-Leg Bridge Hold","video_id":"JkdDIbfxMTQ","video_url":"https://www.youtube.com/shorts/JkdDIbfxMTQ","before":{"purpose":"Develop single-leg hip extension control during a timed hold.","description":"Lie on your back, plant one foot and hold the other leg as shown. Lift to a level-hip bridge and hold for the assigned seconds while breathing; lower to finish. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Hips level. Ribs settled. Breathe steadily. Avoid: Counting repetitions instead of hold time, arching the back or holding after the hips drop.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Single-leg hip strength and control.","description":"Lift your hips with one foot on the floor and hold the position.","coaching_cues":"Cue: Hips level. Squeeze your hip. Avoid: Do not let your hips drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ACT09","name":"Table Position — 6-Movement Activation Series","video_id":"i7Kdkh2eSqE","video_url":"https://www.youtube.com/shorts/i7Kdkh2eSqE","before":{"purpose":"Prepare controlled activation in the demonstrated table-position series.","description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","coaching_cues":"Cue: Steady support. Control transitions. Breathe. Avoid: Letting the shoulders collapse, rushing transitions or adding movements not assigned.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":null,"admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified."},"review_status":"sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified"},{"code":"ACT10","name":"Seated Leg Raise Series","video_id":"licUqHf0kuw","video_url":"https://www.youtube.com/shorts/licUqHf0kuw","before":{"purpose":"Practise controlled seated leg movement with a steady trunk.","description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","coaching_cues":"Cue: Sit tall. Move smoothly. Use a small range. Avoid: Throwing the legs, rocking backward to gain height or forcing hip range.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":null,"admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified."},"review_status":"sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified"},{"code":"ACT11","name":"Superman Activation Series","video_id":"nDrQyHNwtRg","video_url":"https://www.youtube.com/shorts/nDrQyHNwtRg","before":{"purpose":"Practise controlled back-body activation in the demonstrated series.","description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","coaching_cues":"Cue: Length before height. Easy breathing. Small controlled lifts. Avoid: Throwing limbs upward, straining the neck or forcing the lower back into an arch.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":null,"admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified."},"review_status":"sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified"},{"code":"ACT12","name":"Glute Bridge Activation Series","video_id":"TYSVGbdo-lI","video_url":"https://www.youtube.com/shorts/TYSVGbdo-lI","before":{"purpose":"Practise controlled hip extension through the demonstrated bridge variations.","description":"Sequence not yet verified. Watch the full demonstration first. Ask Coach Du to confirm the movement sequence and starting positions before your first session; use only the assigned variations in the confirmed order. Keep transitions controlled and use the sets, repetitions or time on your training sheet.","coaching_cues":"Cue: Level hips. Ribs settled. Control each change. Avoid: Arching the lower back, rushing changes or treating every variation as extra assigned volume.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified.\nCoaching audit 2026-11-15: sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":null,"admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied. Preserve as one series; demonstrated movement order has not been verified."},"review_status":"sequence-pending-coach-verification; general-cues-only; demo-not-independently-verified"},{"code":"ANK01","name":"Calf Raise","video_id":"C3BmRILCdK8","video_url":"https://www.youtube.com/shorts/C3BmRILCdK8","before":{"purpose":"Develop controlled calf strength through the assigned ankle range.","description":"Stand with feet stable and use light hand support if needed. Rise through the balls of the feet and lower smoothly; use the one- or two-leg version prescribed. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Rise tall. Keep ankles aligned. Control down. Avoid: Rolling onto the outside of the foot, bouncing or adding load before balance is steady.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Warm-up + strength","description":"Rise onto your toes, then lower with control.","coaching_cues":"Cue: Up tall. Control down. Avoid: Do not roll your ankle out.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ANK02","name":"Bent-Knee Soleus Hold","video_id":"OAedc9Bl7rc","video_url":"https://www.youtube.com/shorts/OAedc9Bl7rc","before":{"purpose":"Develop calf capacity with the knee bent during a timed hold.","description":"Use stable hand support if needed. Keep the knee comfortably bent, raise the heel to the demonstrated position and hold for the prescribed seconds while breathing. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Knee stays bent. Heel steady. Foot aligned. Avoid: Straightening the knee, rolling the ankle outward or forcing a painful heel height.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 1 onward","description":"Bend your knee slightly, rise onto your toes and hold.","coaching_cues":"Cue: Heel high. Knee bent. Avoid: Do not roll your ankle out.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ANK03","name":"Calf ISO Hold","video_id":"IcitpPYKq2c","video_url":"https://www.youtube.com/shorts/IcitpPYKq2c","before":{"purpose":"Develop calf strength and ankle control during a timed hold.","description":"Stand with light support if needed and rise onto the balls of the feet. Hold the assigned one- or two-leg position for the prescribed seconds, then lower under control. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Stand tall. Heel steady. Keep breathing. Avoid: Bouncing, rolling the ankle or staying up after control is lost.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 1","description":"Rise onto your toes and hold at the top.","coaching_cues":"Cue: Stay tall on your toes. Avoid: Do not let your heel drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"ANK04","name":"Tibialis Raise","video_id":"4bidZUlkXV4","video_url":"https://www.youtube.com/shorts/4bidZUlkXV4","before":{"purpose":"Develop control of the muscles that lift the front of the foot.","description":"Keep heels grounded in the supported position shown. Lift the toes and forefeet toward the shins, then lower smoothly without shifting the whole body. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Heels down. Toes up. Control the return. Avoid: Rocking backward and forward, lifting the heels or forcing ankle range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 1 onward","description":"Keep your heels down and lift your toes toward you.","coaching_cues":"Cue: Toes up. Heels down. Avoid: Do not rock your whole body.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE01","name":"Dead Bug","video_id":"wJbZ9qqVZ2Q","video_url":"https://www.youtube.com/shorts/wJbZ9qqVZ2Q","before":{"purpose":"Practise trunk control while the opposite arm and leg move.","description":"Lie on a mat with arms above the chest and hips and knees bent. Reach the opposite arm and leg away only as far as the lower back stays controlled; return and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Ribs settled. Reach slowly. Breathe out. Avoid: Arching the lower back, rushing or reaching farther than you can control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Warm-up + core","description":"Lie on your back and slowly move opposite arm and leg away.","coaching_cues":"Cue: Keep your back controlled. Avoid: Do not let your back lift.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE02","name":"Front Plank","video_id":"cQ7fXKV7LlQ","video_url":"https://www.youtube.com/shorts/cQ7fXKV7LlQ","before":{"purpose":"Develop trunk stability while maintaining a straight-body hold.","description":"Place forearms on a mat with elbows under shoulders and use the prescribed knee or toe support. Hold the body in one line for the assigned time while breathing. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Long body. Gentle brace. Keep breathing. Avoid: Sagging or hiking the hips, straining the neck or holding beyond good alignment.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Core menu","description":"Hold your body straight on your elbows and toes.","coaching_cues":"Cue: Straight body. Stay strong. Avoid: Do not let your hips drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE03","name":"Side Plank","video_id":"HtGt0ISXRcE","video_url":"https://www.youtube.com/shorts/HtGt0ISXRcE","before":{"purpose":"Develop lateral trunk and hip stability.","description":"Lie on your side with the elbow under the shoulder. Lift into the prescribed knee- or foot-supported side plank and hold a straight line for the assigned time. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Push the floor away. Lift hips. Breathe. Avoid: Collapsing into the shoulder, rotating the chest or holding after the hips drop.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Core menu","description":"Hold your body straight on one elbow and the side of your foot.","coaching_cues":"Cue: Hips up. Body straight. Avoid: Do not let your hips drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE04","name":"Bird Dog","video_id":"zPEiaA3TIl4","video_url":"https://www.youtube.com/shorts/zPEiaA3TIl4","before":{"purpose":"Practise trunk stability during opposite arm and leg movement.","description":"Start on hands and knees, hands under shoulders and knees under hips. Reach the opposite arm and leg long, return slowly and alternate as assigned. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Reach long. Level hips. Keep the back quiet. Avoid: Lifting limbs so high the back arches, twisting the pelvis or shifting weight sharply.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Core + home prehab","description":"From hands and knees, reach opposite arm and leg away.","coaching_cues":"Cue: Keep your body still. Avoid: Do not twist your hips.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE05","name":"Plank Shoulder Tap","video_id":"-jpIJVsQaFo","video_url":"https://www.youtube.com/shorts/-jpIJVsQaFo","before":{"purpose":"Develop trunk control while briefly supporting on one arm.","description":"Start in the prescribed push-up position on a mat, feet wide enough for balance. Lift one hand to tap the opposite shoulder and replace it slowly before switching. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Press the floor. Quiet hips. Slow tap. Avoid: Rocking side to side, dropping the hips or rushing the hand change.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Core progression","description":"Hold a push-up position and tap the opposite shoulder.","coaching_cues":"Cue: Keep your hips still. Avoid: Do not rock side to side.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"CORE06","name":"Hollow Hold","video_id":"FoEa8jNHFJA","video_url":"https://www.youtube.com/shorts/FoEa8jNHFJA","before":{"purpose":"Develop trunk control while the arms and legs create a longer lever.","description":"Lie on a mat and set the arm and leg position demonstrated. Lift or extend only as far as the lower back stays controlled; shorten the position if needed and hold for the assigned time. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Ribs down. Reach long. Keep breathing. Avoid: Arching the back, pulling the neck forward or using a longer lever than you can hold.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Core progression","description":"Lie on your back and hold your arms and legs away from the floor.","coaching_cues":"Cue: Back down. Stay tight. Avoid: Do not let your back lift.","admin_note