es":"Cue: Small steps. Quick ground contact. Avoid: Do not take big steps.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"SPR04","name":"Straight-Leg Run","video_id":"CmsZXZ61Iwg","video_url":"https://www.youtube.com/shorts/CmsZXZ61Iwg","before":{"purpose":"Practise controlled leg cycling and contacts beneath the body.","description":"Use a clear lane and the speed demonstrated. Run with long legs and small, natural knee movement, striking down close beneath the hips rather than reaching ahead. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Long legs. Tall hips. Contact under you. Avoid: Locking the knees, leaning back or kicking the feet far in front.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session sprint prep","description":"Run forward with straight legs striking down under you.","coaching_cues":"Cue: Stay tall. Strike under you. Avoid: Do not reach too far forward.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"SPR05","name":"Dribble Run","video_id":"HKykH7ctpbo","video_url":"https://www.youtube.com/shorts/HKykH7ctpbo","before":{"purpose":"Practise compact running rhythm with feet working beneath the hips.","description":"Use a clear lane and the dribble height shown. Make small cycling actions under the body while moving forward at the assigned speed. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Cycle small. Stay tall. Feet under hips. Avoid: Reaching ahead, lifting the knees beyond the assigned drill or rushing out of rhythm.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session sprint prep","description":"Make quick running circles with your feet under your body.","coaching_cues":"Cue: Quick feet under your hips. Avoid: Do not reach forward.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"SPR06","name":"Fast Feet → Run","video_id":"","video_url":"","before":{"purpose":"Practise moving from a quick-foot rhythm into a controlled run.","description":"On a clear lane, perform the quick-foot action shown and transition into the assigned run. Keep arm and leg actions coordinated and allow room to slow down. Follow the assigned effort or time; stop if pain or loss of control develops.","coaching_cues":"Cue: Quick rhythm. Smooth transition. Run through. Avoid: Stomping in place, forcing a sudden reach forward or adding unassigned sprint effort.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Retained in library; removed from current Standard Warm-Up","description":"Use quick feet, then move smoothly into a run.","coaching_cues":"Cue: Quick feet, then go. Avoid: Do not stand up too early.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR01","name":"Split Squat","video_id":"fq72qz8JHtU","video_url":"https://www.youtube.com/shorts/fq72qz8JHtU","before":{"purpose":"Develop single-leg strength and control in a split stance.","description":"Stand in a stable split stance. Bend both knees to lower within the assigned range, then push through the front foot to return; use support or load only as prescribed. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Front foot grounded. Knee follows toes. Control down. Avoid: Knees collapsing inward, losing balance or forcing the rear knee onto the floor.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 1 onward","description":"Stand in a split stance, lower down, then stand back up.","coaching_cues":"Cue: Stay tall. Knee over foot. Avoid: Do not let your knee fall in.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR02","name":"Step-Up","video_id":"Tdn9-s7-YPc","video_url":"https://www.youtube.com/shorts/Tdn9-s7-YPc","before":{"purpose":"Develop single-leg strength and balance while stepping onto a box.","description":"Use a stable step of the assigned height and place the whole lead foot on it. Push through that leg to stand tall, then lower back down under control. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Whole foot on. Lead leg works. Slow down. Avoid: Jumping off the trailing leg, knee collapse or using a step too high to control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 1 onward","description":"Step onto the box and stand tall on the top leg.","coaching_cues":"Cue: Push through the top leg. Avoid: Do not jump off the back leg.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR03","name":"Single-Leg RDL","video_id":"o1SF5gKsVH0","video_url":"https://www.youtube.com/shorts/o1SF5gKsVH0","before":{"purpose":"Develop hip-hinge strength and single-leg balance.","description":"Stand on one leg with a soft knee and use support if assigned. Send the hips backward as the other leg reaches behind, then return tall while keeping the pelvis level. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Hips back. Long back. Hips face down. Avoid: Opening the pelvis, rounding the back or reaching lower than balance allows.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Form 3/L6 immediately; Form 2 by Week 4","description":"Stand on one leg and push your hips back as the other leg moves behind you.","coaching_cues":"Cue: Hips back. Stay balanced. Avoid: Do not open your hips.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR04","name":"Reverse Lunge","video_id":"PPu6dREwL64","video_url":"https://www.youtube.com/shorts/PPu6dREwL64","before":{"purpose":"Develop controlled leg strength through a backward stepping action.","description":"Stand tall with space behind you. Step back, bend both knees within a comfortable assigned range and push through the front foot to return. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Step back softly. Front foot grounded. Control the return. Avoid: Stepping onto a narrow line, knees collapsing inward or slamming the rear knee down.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Week 4 + reusable","description":"Step backward, lower down, then return to standing.","coaching_cues":"Cue: Step back. Stay tall. Avoid: Do not let your front knee fall in.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR05","name":"Bridge Walkout","video_id":"EdyfB2_DkC8","video_url":"https://www.youtube.com/shorts/EdyfB2_DkC8","before":{"purpose":"Develop hamstring control while maintaining a bridge position.","description":"Lie on a mat, plant both feet and lift into a controlled bridge. Take small heel steps outward and back as demonstrated, shortening the distance if the hips cannot stay steady. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Small heel steps. Hips steady. Ribs settled. Avoid: Arching the back, letting hips drop or walking out beyond control.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Weeks 3–5","description":"Lift your hips and slowly walk your feet away and back.","coaching_cues":"Cue: Keep your hips up. Avoid: Do not let your hips drop.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR06","name":"Single-Leg Eccentric Box Squat — Explosive Up","video_id":"C6DJkHnaJH0","video_url":"https://www.youtube.com/shorts/C6DJkHnaJH0","before":{"purpose":"Develop controlled single-leg lowering and a purposeful upward drive.","description":"Use a stable box at the assigned height. Lower on the working leg under control to the demonstrated box contact, then drive upward intentionally using the support or reset shown; do not add an unassigned jump. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Lower slowly. Knee follows toes. Drive up with intent. Avoid: Dropping onto the box, rocking to escape the bottom position or adding load before control is reliable.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied.\nCoaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":"Lower with control; drive upward intentionally.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied."},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"STR07","name":"Supported Deep Knee Bend (Assisted Knee-Over-Toe Squat)","video_id":"OOH7c2sKip8","video_url":"https://www.youtube.com/shorts/OOH7c2sKip8","before":{"purpose":"Explore supported knee and ankle range with controlled leg strength.","description":"Hold a stable support and match the stance shown. Lower into a comfortable supported knee bend, allowing the knee to travel as demonstrated, then return under control. Use only the assigned load and volume; stop if pain or loss of control develops.","coaching_cues":"Cue: Use support. Follow the toes. Move comfortably. Avoid: Forcing depth, bouncing into the bottom or copying extra load or range not assigned.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied.\nCoaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":null,"description":null,"coaching_cues":"Use support and comfortable knee travel; never force the range.","admin_notes":"Import batch exercise-video-expansion-20. Exact mapping supplied and release authorized by Coach Du. Playback and movement verification pending; do not treat this entry as independently verified. Coaching sequence, setup, equipment and dosage require review; no default prescription supplied."},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU01","name":"Ankle Rock","video_id":"6Dlac5mxD6k","video_url":"https://www.youtube.com/shorts/6Dlac5mxD6k","before":{"purpose":"Prepare the ankle for controlled forward knee travel.","description":"Use a split or kneeling stance and support as shown. Guide the front knee forward over the foot while the heel remains grounded, then return slowly. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Heel down. Knee follows toes. Easy range. Avoid: Lifting the heel, collapsing the arch or forcing a painful range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up + home prehab","description":"Move your knee forward over your toes while your heel stays down.","coaching_cues":"Cue: Heel down. Knee forward. Avoid: Do not lift your heel.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU02","name":"Straight-Leg Hamstring Kick","video_id":"UEzzeExMLLw","video_url":"https://www.youtube.com/shorts/UEzzeExMLLw","before":{"purpose":"Prepare the back of the thigh through controlled leg swings while walking.","description":"Stand tall with space ahead. Walk forward and lift one long leg within a comfortable range, then lower with control and alternate. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Stay tall. Reach comfortably. Control down. Avoid: Leaning back, snapping the knee straight or forcing the foot higher.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up","description":"Walk forward and lift one straight leg in front of you.","coaching_cues":"Cue: Stay tall. Leg straight. Avoid: Do not lean back.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU03","name":"Walking Lunge + Rotation","video_id":"e6BRge-9RdY","video_url":"https://www.youtube.com/shorts/e6BRge-9RdY","before":{"purpose":"Prepare the hips and trunk with a controlled lunge and turn.","description":"Step into a comfortable walking lunge. Keep the front foot grounded and rotate the chest toward the front leg as shown, then return and step through. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Stable foot. Turn through chest. Stay controlled. Avoid: Forcing a long stride, twisting the front knee or rushing the rotation.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up","description":"Step into a lunge and turn your chest toward the front leg.","coaching_cues":"Cue: Step long. Stay tall. Avoid: Do not let your knee fall in.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU04","name":"Adductor Rock-Back","video_id":"VQOIhPcPNZA","video_url":"https://www.youtube.com/shorts/VQOIhPcPNZA","before":{"purpose":"Explore inner-thigh mobility with a controlled hip rock.","description":"Start on hands and knees on a mat and extend one leg to the side as demonstrated. Rock the hips backward in a gentle range and return slowly. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Hips back. Long back. Gentle range. Avoid: Forcing the stretch, rounding deeply or continuing through groin or knee pain.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up + home work","description":"Start on hands and knees, move one leg out, then sit your hips back.","coaching_cues":"Cue: Hips back. Move slowly. Avoid: Do not force the stretch.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU05","name":"High-Knee Hip Rotation Out","video_id":"ZchkCbWjOXw","video_url":"https://www.youtube.com/shorts/ZchkCbWjOXw","before":{"purpose":"Prepare controlled outward rotation of the hip.","description":"Stand tall with support if needed. Lift one knee and open the hip outward through a comfortable arc, then return and alternate as assigned. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Tall body. Quiet pelvis. Move from hip. Avoid: Twisting the whole trunk, forcing the knee outward or losing balance to gain range.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up","description":"Lift one knee up and slowly open it out to the side.","coaching_cues":"Cue: Knee up. Open the hip. Avoid: Do not twist your whole body.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU06","name":"Leg Swing Front / Back","video_id":"nL-SiujsIMk","video_url":"https://www.youtube.com/shorts/nL-SiujsIMk","before":{"purpose":"Prepare front-to-back hip movement with controlled leg swings.","description":"Stand beside a stable support. Swing one leg gently forward and backward while the pelvis and trunk stay steady; build only the comfortable range shown. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Stand tall. Easy swing. Quiet trunk. Avoid: Forcing height, arching the back or swinging beyond balance.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up","description":"Swing one leg forward and backward while standing tall.","coaching_cues":"Cue: Stay tall. Control the swing. Avoid: Do not swing out of control.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"},{"code":"WU07","name":"Leg Swing Side / Side","video_id":"7euYeH7erNw","video_url":"https://www.youtube.com/shorts/7euYeH7erNw","before":{"purpose":"Prepare side-to-side hip movement with controlled leg swings.","description":"Face a stable support and hold it lightly. Swing one leg across and away from the body within a comfortable range, keeping the pelvis mostly forward. Keep the movement comfortable; do not force a stretch.","coaching_cues":"Cue: Tall body. Easy rhythm. Control the return. Avoid: Twisting the whole trunk, forcing range or swinging into another person.","admin_notes":"Coaching audit 2026-11-15: named-exercise-text-reviewed; demo-not-independently-verified. Library guidance does not change assigned prescriptions."},"after":{"purpose":"Every-session warm-up","description":"Swing one leg across your body and out to the side.","coaching_cues":"Cue: Stay tall. Control the swing. Avoid: Do not turn your whole body.","admin_notes":null},"review_status":"named-exercise-text-reviewed; demo-not-independently-verified"}]$changes$::jsonb;
  row_data jsonb;
  current_content jsonb;
  protected_before jsonb;
  protected_after jsonb;
  programme_before jsonb;
  programme_after jsonb;
BEGIN
  LOCK TABLE public.exercises IN SHARE ROW EXCLUSIVE MODE;
  LOCK TABLE public.programmes,public.programme_weeks,public.training_days,public.session_blocks,public.saved_blocks,public.saved_block_items,public.athlete_overrides,public.cohort_overrides,public.athletes,public.cohorts,public.professional_members,public.programme_versions,public.feedback,public.workout_item_completions IN SHARE MODE;
  SELECT jsonb_object_agg(e.code,to_jsonb(e)-ARRAY['description','purpose','coaching_cues','admin_notes','updated_at']) INTO protected_before FROM public.exercises e;
  programme_before := jsonb_build_object('programmes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programmes t),'programme_weeks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_weeks t),'training_days',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.training_days t),'session_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.session_blocks t),'saved_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_blocks t),'saved_block_items',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_block_items t),'athlete_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athlete_overrides t),'cohort_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohort_overrides t),'athletes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athletes t),'cohorts',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohorts t),'professional_members',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.professional_members t),'programme_versions',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_versions t),'feedback',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.feedback t),'workout_item_completions',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.workout_item_completions t));
  IF jsonb_array_length(changes) <> 85 THEN RAISE EXCEPTION 'Expected 85 audited entries'; END IF;
  FOR row_data IN SELECT value FROM jsonb_array_elements(changes) LOOP
    SELECT jsonb_build_object('description',e.description,'purpose',e.purpose,'coaching_cues',e.coaching_cues,'admin_notes',e.admin_notes) INTO current_content FROM public.exercises e
      WHERE code=row_data->>'code' AND name=row_data->>'name'
        AND video_id IS NOT DISTINCT FROM row_data->>'video_id'
        AND video_url IS NOT DISTINCT FROM row_data->>'video_url';
    IF NOT FOUND THEN RAISE EXCEPTION 'Exercise identity/video changed: %',row_data->>'code'; END IF;
    IF current_content = row_data->'after' THEN CONTINUE; END IF;
    IF current_content IS DISTINCT FROM row_data->'before' THEN
      RAISE EXCEPTION 'Concurrent coaching edit: %; re-audit before updating',row_data->>'code';
    END IF;
    UPDATE public.exercises SET description=row_data->'after'->>'description',
      purpose=row_data->'after'->>'purpose',coaching_cues=row_data->'after'->>'coaching_cues',
      admin_notes=row_data->'after'->>'admin_notes',updated_at=now()
      WHERE code=row_data->>'code';
  END LOOP;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(changes) r JOIN public.exercises e ON e.code=r->>'code'
    WHERE jsonb_build_object('description',e.description,'purpose',e.purpose,'coaching_cues',e.coaching_cues,'admin_notes',e.admin_notes) IS DISTINCT FROM r->'after') THEN RAISE EXCEPTION 'Coaching content persistence mismatch'; END IF;
  SELECT jsonb_object_agg(e.code,to_jsonb(e)-ARRAY['description','purpose','coaching_cues','admin_notes','updated_at']) INTO protected_after FROM public.exercises e;
  IF protected_before IS DISTINCT FROM protected_after THEN RAISE EXCEPTION 'Protected exercise fields changed'; END IF;
  programme_after := jsonb_build_object('programmes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programmes t),'programme_weeks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_weeks t),'training_days',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.training_days t),'session_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.session_blocks t),'saved_blocks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_blocks t),'saved_block_items',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.saved_block_items t),'athlete_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athlete_overrides t),'cohort_overrides',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohort_overrides t),'athletes',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.athletes t),'cohorts',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.cohorts t),'professional_members',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.professional_members t),'programme_versions',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.programme_versions t),'feedback',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.feedback t),'workout_item_completions',(select md5(coalesce(string_agg(to_jsonb(t)::text,'' order by id),'')) from public.workout_item_completions t));
  IF programme_before IS DISTINCT FROM programme_after THEN RAISE EXCEPTION 'Approved programme content changed'; END IF;
END
$coaching$;
